#include <bits/stdc++.h>
using namespace std;

int main(){
    int n, T;
    if (scanf("%d %d", &n, &T) != 2) return 0;
    vector<pair<int,int>> v(n);
    for (int i = 0; i < n; i++) scanf("%d", &v[i].first);   // tipo
    for (int i = 0; i < n; i++) scanf("%d", &v[i].second);  // preco
    sort(v.begin(), v.end());

    vector<int> pos(T+1, 0), st(T+1, 0), en(T+1, 0);
    for (int i = 0; i < n; i++){
        if (i == 0 || v[i].first != v[i-1].first) st[v[i].first] = i;
        if (i == n-1 || v[i].first != v[i+1].first) en[v[i].first] = i+1;
    }

    const int INF = INT_MAX;
    vector<int> cur(T+1, INF);
    set<pair<int,int>> s;
    for (int ty = 1; ty <= T; ty++){
        if (st[ty] < en[ty]){
            cur[ty] = v[st[ty]].second;
            s.insert({cur[ty], ty});
        }
    }

    long long ans = 0;
    int C; scanf("%d", &C);
    while (C--){
        int u; scanf("%d", &u);
        if (u == 0){
            if (!s.empty()){
                auto it = s.begin();
                int price = it->first, ty = it->second;
                ans += price;
                s.erase(it);
                pos[ty]++;
                if (pos[ty] < en[ty]){
                    cur[ty] = v[pos[ty]].second;
                    s.insert({cur[ty], ty});
                } else cur[ty] = INF;
            }
        } else {
            if (pos[u] < en[u]){
                ans += v[pos[u]].second;
                s.erase({cur[u], u});
                pos[u]++;
                if (pos[u] < en[u]){
                    cur[u] = v[pos[u]].second;
                    s.insert({cur[u], u});
                } else cur[u] = INF;
            }
        }
    }
    printf("%lld\n", ans);
    return 0;
}
